 if(o.required_participant&&o.required_participant->empty())return common_failure("InvalidObjectiveParticipant");if(o.required_recipient&&o.required_recipient->id.empty())return common_failure("InvalidObjectiveRecipient");
 if(static_cast<Integer>(o.use_policy)<0||static_cast<Integer>(o.use_policy)>1)return common_failure("UnknownObjectiveUsePolicy");
 if(o.report_required&&(o.report_recipient.id.empty()||(o.report_gate&&o.report_gate->tick<0)))return common_failure("InvalidObjectiveReportTerms");if(!o.report_required&&o.report_gate)return common_failure("UnexpectedObjectiveReportGate");
