 if(const auto*c=std::get_if<LegacyGoalCriterion>(&o.criterion)){if(c->goal_kind.empty()||c->rule_version.empty()||o.craft||o.professional_target||!o.allowed_professional_kinds.empty()||o.required_source_terms)return common_failure("InvalidLegacyObjectiveCriterion");}
