bool same_terms(const FrozenObjectiveBase&a,const FrozenObjectiveBase&b){
 if(a.id!=b.id||a.task_id!=b.task_id||!same(a.task_acceptance_source,b.task_acceptance_source)||!same_terms_revision(a.task_terms,b.task_terms)||!same_objective_base_criterion(a.criterion,b.criterion)||a.goal.index()!=b.goal.index()||a.required_participant!=b.required_participant||!same(a.required_recipient,b.required_recipient)||!same(a.professional_target,b.professional_target)||a.allowed_professional_kinds!=b.allowed_professional_kinds||a.required_source_terms.has_value()!=b.required_source_terms.has_value()||a.craft.has_value()!=b.craft.has_value()||a.allow_natural_event!=b.allow_natural_event||a.allow_partial!=b.allow_partial||a.record_contribution!=b.record_contribution||a.use_policy!=b.use_policy||a.acceptance_purpose!=b.acceptance_purpose||a.completion_gate.tick!=b.completion_gate.tick||a.completion_gate.inclusive!=b.completion_gate.inclusive||a.report_required!=b.report_required||!same(a.report_recipient,b.report_recipient)||a.report_gate.has_value()!=b.report_gate.has_value()||!same(a.observer.observer,b.observer.observer)||a.observer.registered_scope_ref!=b.observer.registered_scope_ref)return false;
 if(a.required_source_terms&&!same_terms_revision(*a.required_source_terms,*b.required_source_terms))return false;
 if(a.report_gate&&(a.report_gate->tick!=b.report_gate->tick||a.report_gate->inclusive!=b.report_gate->inclusive))return false;
 if(auto*x=std::get_if<ObjectiveQuantityGoal>(&a.goal)){auto&y=std::get<ObjectiveQuantityGoal>(b.goal);if(x->amount!=y.amount||x->unit_id!=y.unit_id)return false;}else{auto&predicate=std::get<ObjectivePredicateGoal>(a.goal);auto&y=std::get<ObjectivePredicateGoal>(b.goal);if(predicate.source_domain!=y.source_domain||predicate.source_kind!=y.source_kind)return false;}
 if(a.craft){auto&x=*a.craft;auto&y=*b.craft;if(!same(x.order_ref,y.order_ref)||x.job_id!=y.job_id||x.item_id!=y.item_id||!same(x.from_owner,y.from_owner)||!same(x.to_owner,y.to_owner)||x.acceptor_actor_id!=y.acceptor_actor_id||x.allow_partial!=y.allow_partial)return false;}return true;
}
Status check_evidence(const FrozenObjectiveBase&o,const ObjectiveEvidenceSnapshot&e,const WorldMoment&now){
 if(e.source_owner.empty()||e.settlement_key.empty())return common_failure("ObjectiveSettlementIdentityMissing",o.id,ErrorKind::internal);
 auto time=not_future(e.completed_at,now);if(!time.ok)return time;auto gate=calendar_deadline_accepts(o.completion_gate.tick,o.completion_gate.inclusive,e.completed_at);if(!gate.ok)return {false,{},gate.error};if(!gate.value)return common_failure("ObjectiveDeadlineElapsed",o.id);
 if(o.required_participant&&e.actual_participant!=o.required_participant)return common_failure("ParticipantNotInOutcome");if(std::holds_alternative<ProfessionalCriterion>(o.criterion)&&!e.actual_participant&&!o.allow_natural_event)return common_failure("ParticipantNotInOutcome");if(o.required_recipient&&(!e.recipient||!same(*o.required_recipient,*e.recipient)))return common_failure("RecipientMismatch");if(!same(o.professional_target,e.target))return common_failure("ObjectiveTargetMismatch");
 if(auto*q=std::get_if<ObjectiveQuantityGoal>(&o.goal)){auto*m=std::get_if<ObjectiveMeasured>(&e.measure);if(!m||m->unit_id!=q->unit_id)return common_failure("UnitMismatch");if(m->amount<=0)return common_failure("OutcomeNotYetComplete");}else{auto*m=std::get_if<ObjectivePredicate>(&e.measure);auto&p=std::get<ObjectivePredicateGoal>(o.goal);if(!m||m->predicate_source.domain!=p.source_domain||m->predicate_source.kind!=p.source_kind||!valid(m->predicate_source))return common_failure("ObjectivePredicateMismatch");}
 for(std::size_t i=0;i<e.original_result_refs.size();++i){if(!valid(e.original_result_refs[i]))return common_failure("ObjectiveResultSourceMissing");for(std::size_t j=0;j<i;++j)if(same(e.original_result_refs[i],e.original_result_refs[j]))return common_failure("DuplicateObjectiveResultSource");}return common_success();
}
