  const auto*d=tasks.deliveries.find(c.task_delivery_result_ref.id);if(c.task_delivery_result_ref.domain!="tasks"||c.task_delivery_result_ref.kind!="task_delivery"||!d||d->task_id!=o.task_id||!d->completed_at)return fail<ObjectiveEvidenceSnapshot>("CraftTaskDeliverySourceMismatch");auto head=source_header(common,c.task_delivery_result_ref);if(!head.ok)return {false,{},head.error};auto at=compare_world_moments(*d->completed_at,c.completed_at);if(!at.ok)return {false,{},at.error};if(at.value)return fail<ObjectiveEvidenceSnapshot>("CraftTaskDeliveryTimeMismatch");
