Outcome<ObjectiveAcceptedMeasure> available_measure(const TaskObjectiveBaseState&s,const FrozenObjectiveBase&o,const ObjectiveEvidenceSnapshot&e){
 Integer already=0,used=0;bool predicate_done=false,predicate_used=false;
 for(const auto&row:s.acceptances.rows()){
  const auto&a=row.second;if(!a.accepted)continue;const auto*prior=s.objectives.find(a.objective_id);if(!prior||!a.source_settlement_key)return fail<ObjectiveAcceptedMeasure>("ObjectiveAcceptanceBindingMissing",a.acceptance_id,ErrorKind::internal);
  if(a.objective_id==o.id){if(auto*q=std::get_if<ObjectiveMeasured>(&a.measure)){auto n=checked_add(already,q->amount);if(!n.ok)return {false,{},n.error};}else predicate_done=true;}
  if(a.source_owner!=e.source_owner||*a.source_settlement_key!=e.settlement_key)continue;
  const bool same_pool=o.use_policy==ObjectiveUsePolicy::exclusive||prior->use_policy==ObjectiveUsePolicy::exclusive||prior->acceptance_purpose==o.acceptance_purpose;
  if(!same_pool)continue;if(a.measure.index()!=e.measure.index())return fail<ObjectiveAcceptedMeasure>("ObjectiveSourceMeasureChanged",a.acceptance_id,ErrorKind::internal);
  if(auto*q=std::get_if<ObjectiveMeasured>(&a.measure)){if(q->unit_id!=std::get<ObjectiveMeasured>(e.measure).unit_id)return fail<ObjectiveAcceptedMeasure>("UnitMismatch");auto n=checked_add(used,q->amount);if(!n.ok)return {false,{},n.error};}else predicate_used=true;
 }
 if(const auto*q=std::get_if<ObjectiveQuantityGoal>(&o.goal)){const auto&m=std::get<ObjectiveMeasured>(e.measure);if(already>=q->amount)return fail<ObjectiveAcceptedMeasure>("TaskObjectiveAlreadyComplete");if(used>=m.amount)return fail<ObjectiveAcceptedMeasure>("ContributionAlreadyUsed");return {true,ObjectiveMeasured{std::min(q->amount-already,m.amount-used),m.unit_id},{}};}
 if(predicate_done)return fail<ObjectiveAcceptedMeasure>("TaskObjectiveAlreadyComplete");if(predicate_used)return fail<ObjectiveAcceptedMeasure>("ContributionAlreadyUsed");return {true,e.measure,{}};
}
