// 验工成果只消费同一 Task 的不可变 completed 源。金额、目标应用与报告
// 都不在这里发生；participant 来自已经反验的真实合格期间，不取当前人名。
Outcome<ObjectiveEvidenceSnapshot> read_work_objective_evidence(
 const CommonStore& common,const TaskState& tasks,const WorkExecutionRead& reader,
 const FrozenObjectiveBase& objective,const WorkEvidenceSource& evidence){
 if(!reader.bound_to(common,tasks)||!tasks.work_execution)
  return fail<ObjectiveEvidenceSnapshot>("WorkObjectiveCandidateMismatch",objective.id,ErrorKind::internal);
 auto valid_terms=validate_terms(objective);if(!valid_terms.ok)return {false,{},valid_terms.error};
 const auto*criterion=std::get_if<WorkCriterion>(&objective.criterion);
 if(!criterion)return fail<ObjectiveEvidenceSnapshot>("WorkObjectiveCriterionRequired",objective.id);
 SourceRef ref;
 if(const auto*p=std::get_if<PatrolResult>(&evidence.source))ref={"tasks","patrol_work_result",p->fact_id};
 else if(const auto*p=std::get_if<SupervisedResult>(&evidence.source))ref={"tasks","supervised_work_result",p->fact_id};
 else return fail<ObjectiveEvidenceSnapshot>("LegacyWorkDoesNotMeetSelectedWorkCriterion",objective.id);
 auto read=reader.read_result(ref,1);if(!read.ok)return {false,{},read.error};
 const auto&result=*read.value;
 if(result.task_id!=objective.task_id||result.kind!=criterion->work_kind||
    !work_detail::same(result.authorization,criterion->authorization)||
    result.disposition!=WorkResultDisposition::completed)
  return fail<ObjectiveEvidenceSnapshot>("WorkObjectiveSourceMismatch",ref.id);
 auto work=reader.read_work(result.work_id);if(!work.ok)return {false,{},work.error};
 const auto*accepted=tasks.work_execution->acceptances.find(work.value->acceptance_source_ref);
 if(!accepted||accepted->original_task_acceptance.source_schema!=1||
    !same(accepted->original_task_acceptance.source_ref,objective.task_acceptance_source))
  return fail<ObjectiveEvidenceSnapshot>("WorkObjectiveAcceptanceMismatch",ref.id);
 std::optional<StableId> sole_actor;bool multiple=false,required_present=false;
 for(const auto&id:work.value->accepted_period_refs){
  auto period=reader.read_period(id);if(!period.ok)return {false,{},period.error};
  if(period.value->credited_half_days==0)continue;
  const auto&actor=period.value->leader_actor_id;
  if(objective.required_participant&&actor==*objective.required_participant)required_present=true;
  if(!sole_actor)sole_actor=actor;else if(*sole_actor!=actor)multiple=true;
 }
 if(!sole_actor)return fail<ObjectiveEvidenceSnapshot>("CompletedWorkHasNoActualParticipant",ref.id,ErrorKind::internal);
 if(objective.required_participant&&!required_present)
  return fail<ObjectiveEvidenceSnapshot>("ParticipantNotInOutcome",*objective.required_participant);
 ObjectiveEvidenceSnapshot out;
 if(objective.required_participant)out.actual_participant=objective.required_participant;
 else if(!multiple)out.actual_participant=sole_actor;
 out.measure=ObjectivePredicate{ref};out.completed_at=result.finished_at;
 out.source_owner="tasks";out.settlement_key=result.fact_id;
 out.original_result_refs={ref,SourceRef{"tasks","work_accepted",accepted->fact_id},
  accepted->original_task_acceptance.source_ref,result.authorization.program_ref};
 return {true,std::move(out),{}};
}
